import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.LX5S0jbT.js";const k=JSON.parse('{"title":"在 Windows 上运行 Pi","description":"","frontmatter":{},"headers":[],"relativePath":"zh/windows.md","filePath":"zh/windows.md"}'),o={name:"zh/windows.md"};function l(d,s,h,n,p,r){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="在-windows-上运行-pi" tabindex="-1">在 Windows 上运行 Pi <a class="header-anchor" href="#在-windows-上运行-pi" aria-label="Permalink to &quot;在 Windows 上运行 Pi&quot;">​</a></h1><p>Pi 可以作为原生 Windows 进程运行，也可以在适用于 Linux 的 Windows 子系统（WSL）中运行。原生 Windows 默认使用 Git Bash 执行 Bash 命令，并可选择向模型暴露 PowerShell。WSL 中的 Pi 使用 Linux 环境及其 Bash 安装。</p><p>安装和认证 Pi 请遵循主<a href="./quickstart.html">快速开始</a>。本页用于选择和配置命令环境。</p><h2 id="选择原生-windows-还是-wsl" tabindex="-1">选择原生 Windows 还是 WSL <a class="header-anchor" href="#选择原生-windows-还是-wsl" aria-label="Permalink to &quot;选择原生 Windows 还是 WSL&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环境</th><th>命令环境</th><th>适用场景</th></tr></thead><tbody><tr><td>原生 Windows + Git Bash</td><td>内置 <code>bash</code> 工具和 <code>!</code> 命令使用 Git Bash</td><td>文件和开发工具主要在 Windows 上</td></tr><tr><td>原生 Windows + <code>powershell</code> 工具</td><td>模型工具调用使用 PowerShell；<code>!</code> 命令仍可用 Bash</td><td>任务依赖 PowerShell 模块或 Windows 原生命令</td></tr><tr><td>WSL</td><td>所选 WSL 发行版中的 Linux Bash 和工具</td><td>文件和工具链已经在 Linux 或 WSL 中</td></tr></tbody></table><h2 id="在原生-windows-上使用-git-bash" tabindex="-1">在原生 Windows 上使用 Git Bash <a class="header-anchor" href="#在原生-windows-上使用-git-bash" aria-label="Permalink to &quot;在原生 Windows 上使用 Git Bash&quot;">​</a></h2><p>对大多数原生 Windows 用户来说，安装 <a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Git for Windows</a> 即可。</p><p>Pi 按以下顺序解析 Bash：</p><ol><li><code>~/.pi/agent/settings.json</code> 中的 <code>shellPath</code></li><li><code>%ProgramFiles%\\Git\\bin\\bash.exe</code> 的 Git Bash</li><li><code>%ProgramFiles(x86)%\\Git\\bin\\bash.exe</code> 的 Git Bash</li><li><code>PATH</code> 上的 <code>bash.exe</code>，包括 Cygwin、MSYS2 或旧版 WSL Bash</li></ol><p>启动 Pi 并输入以下命令验证 shell：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!printf &#39;Bash is working\\n&#39;</span></span></code></pre></div><p>如果 Pi 找不到 Bash，它会报告检查过的位置。安装 Git for Windows、将其他 Bash 可执行文件加入 <code>PATH</code>，或配置 <code>shellPath</code>。</p><h2 id="让模型使用-powershell" tabindex="-1">让模型使用 PowerShell <a class="header-anchor" href="#让模型使用-powershell" aria-label="Permalink to &quot;让模型使用 PowerShell&quot;">​</a></h2><p>可选的 <code>powershell</code> 工具优先通过 <code>pwsh.exe</code> 运行命令，不可用时回退到 Windows PowerShell。它使用 <code>-NoProfile -NonInteractive -ExecutionPolicy Bypass</code> 启动 PowerShell。管理员强制执行的执行策略仍可能优先。</p><p>PowerShell 发现按以下顺序检查这些位置：</p><ol><li><code>PATH</code> 上的 <code>pwsh.exe</code></li><li><code>%ProgramFiles%\\PowerShell\\7\\pwsh.exe</code></li><li><code>PATH</code> 上的 <code>powershell.exe</code></li><li><code>%SystemRoot%\\System32\\WindowsPowerShell\\v1.0\\powershell.exe</code></li></ol><p>要将面向模型的 <code>bash</code> 工具替换为 <code>powershell</code>，在 <code>~/.pi/agent/settings.json</code> 中添加：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;defaultTools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;powershell&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;write&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>[&quot;-bash&quot;, &quot;+powershell&quot;]</code> 效果相同，同时保留你配置的其他默认工具。</p><p>重启 Pi，然后让它运行一个无害的 PowerShell 命令。<code>!</code> 和 <code>!!</code> 编辑器命令仍使用 Bash。<code>powershell</code> 工具仅在 Pi 作为原生 Windows 进程运行时可用。</p><p>其他工具组合见<a href="./settings.html#tools">设置</a>。</p><h2 id="wsl" tabindex="-1">WSL <a class="header-anchor" href="#wsl" aria-label="Permalink to &quot;WSL&quot;">​</a></h2><p>Windows 上的 WSL 路径转换和 WSL 中额外的 Git 分支轮询识别 <code>/mnt/&lt;drive&gt;</code>，而不是自定义挂载根。</p><p>从 Windows 使用旧版 WSL <code>bash.exe</code> 启动器时，Pi 通过 stdin 发送命令，以避免命令行引号问题。</p><h2 id="使用自定义-bash-可执行文件" tabindex="-1">使用自定义 Bash 可执行文件 <a class="header-anchor" href="#使用自定义-bash-可执行文件" aria-label="Permalink to &quot;使用自定义 Bash 可执行文件&quot;">​</a></h2><p>当 Bash 安装在 Pi 无法自动发现的位置时，设置 <code>shellPath</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;shellPath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">cygwin64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bash.exe&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>JSON 使用反斜杠作为转义序列。在 JSON 中书写带反斜杠的 Windows 路径时，每个反斜杠要写两次，如上所示。</p><p>命令前缀、别名和完整的 shell 解析行为见<a href="./shell-aliases.html">配置 shell 命令</a>。</p><h2 id="配置-windows-terminal" tabindex="-1">配置 Windows Terminal <a class="header-anchor" href="#配置-windows-terminal" aria-label="Permalink to &quot;配置 Windows Terminal&quot;">​</a></h2><p>Windows Terminal 会保留或改写一些修饰键。配置 <code>Shift+Enter</code> 和 <code>Alt+Enter</code> 见 <a href="./terminal-setup.html#windows-terminal">Windows Terminal</a>，Pi 的 Windows 和 WSL 快捷键默认值见<a href="./keybindings.html">快捷键</a>。</p>`,31)])])}const w=i(o,[["render",l]]);export{k as __pageData,w as default};
